function haversineMiles(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 3958.8;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function inferUtilityTerritory(facility: FacilityLocation): string {
  const city = facility.city.toLowerCase();
  if (facility.stateOrCountry.includes("CT")) {
    if (city.includes("wallingford")) return "Wallingford Electric Division (Municipal)";
    if (city.includes("norwich") || city.includes("bozrah")) return "Norwich Public Utilities / Bozrah Light & Power";
    if (city.includes("groton")) return "Groton Utilities / Eversource 115 kV";
    if (
      city.includes("new haven") ||
      city.includes("milford") ||
      city.includes("orange") ||
      city.includes("west haven") ||
      city.includes("stratford") ||
      city.includes("trumbull") ||
      city.includes("shelton") ||
      city.includes("bridgeport") ||
      city.includes("north haven")
    ) {
      return "United Illuminating (UI / Avangrid — ISO-NE)";
    }
    return "Eversource Energy (CL&P — ISO-NE)";
  }
  if (facility.stateOrCountry.includes("MA")) {
    if (city.includes("holyoke")) return "Holyoke Gas & Electric (HG&E Hydro — ISO-NE)";
    if (city.includes("worcester") || city.includes("marlborough") || city.includes("lowell")) return "National Grid Massachusetts (ISO-NE)";
    return "Eversource Energy Massachusetts (ISO-NE)";
  }
  if (facility.stateOrCountry.includes("NY")) {
    if (city.includes("poughkeepsie") || city.includes("fishkill") || city.includes("newburgh") || city.includes("kingston")) {
      return "Central Hudson Gas & Electric (NYISO Zone G)";
    }
    if (city.includes("orangeburg")) return "Orange & Rockland Utilities (ConEd — NYISO Zone G)";
    if (city.includes("yorktown") || city.includes("hawthorne")) return "Con Edison Westchester (NYISO Zone H/I)";
    return "National Grid / NYSEG Upstate (NYISO Zone F)";
  }
  if (facility.stateOrCountry.includes("VA")) return "Dominion Energy Virginia (PJM Interconnection)";
  if (facility.stateOrCountry.includes("OR")) return "Bonneville Power Admin (BPA) / PGE / PacifiCorp";
  if (facility.stateOrCountry.includes("WA")) return "Grant County PUD / BPA Hydro Grid";
  if (facility.stateOrCountry.includes("IA")) return "MidAmerican Energy (MISO Wind/Baseload)";
  if (facility.stateOrCountry.includes("NV")) return "NV Energy (Sierra Pacific Power)";
  if (facility.stateOrCountry.includes("GA")) return "Georgia Power (Southern Company)";
  if (facility.stateOrCountry.includes("TN")) return "Tennessee Valley Authority (TVA) / MLGW";
  if (facility.stateOrCountry.includes("TX")) return "Oncor / ERCOT Transmission Grid";
  if (facility.stateOrCountry.includes("CA")) return "Silicon Valley Power (SVP) / PG&E (CAISO)";
  if (facility.stateOrCountry.includes("NC")) return "Duke Energy Carolinas";
  if (facility.stateOrCountry.includes("UT")) return "Rocky Mountain Power (PacifiCorp)";
  if (facility.stateOrCountry.includes("IL")) return "ComEd (Exelon — PJM)";
  if (facility.stateOrCountry.includes("OH")) return "AEP Ohio (PJM Interconnection)";
  if (facility.stateOrCountry.includes("DE")) return "Delmarva Power (Exelon — PJM)";
  return "Regional Bulk Electric System (BES)";
}

function inferInterconnectTier(subtype: DataCenterSubtype): string {
  switch (subtype) {
    case "Hyperscale":
    case "AI Supercluster":
      return "Dedicated 230–500 kV Bulk Substation Switchyard";
    case "Colocation (COLO)":
      return "Dedicated 115–230 kV Substation / Redundant Dual-Ring Tap";
    case "Enterprise Data Center":
      return "69–115 kV Redundant 2N Transmission Tap";
    case "Edge / Small Data Hub":
      return "13.8–34.5 kV Dual Underground Primary Feeders";
    case "Suspected Small-Scale Server Room":
      return "13.8 kV Municipal Pad-Transformer Distribution Feed";
  }
}

export function isNamedSubstation(name: string): boolean {
  const upper = name.toUpperCase();
  return (
    !upper.startsWith("TAP1") &&
    !upper.startsWith("UNKNOWN") &&
    !upper.startsWith("DEADEND") &&
    !upper.startsWith("RISER") &&
    upper !== "NOT AVAILABLE"
  );
}

