export function computeEnrichedTransmissionCorridors(): EnrichedTransmissionCorridor[] {
  const allWaypoints = [
    ...CORRIDOR_TOWN_WAYPOINTS,
    ...POWER_STATIONS.map((s) => ({
      name: s.city === "Falls Village" ? "Canaan (Falls Village)" : s.city,
      state: s.state,
      lat: s.lat,
      lng: s.lng,
    })),
  ];

  return TRANSMISSION_LINES.map((line) => {
    let lengthMiles = 0;
    for (let i = 1; i < line.coordinates.length; i++) {
      lengthMiles += haversineMiles(
        line.coordinates[i - 1][0],
        line.coordinates[i - 1][1],
        line.coordinates[i][0],
        line.coordinates[i][1]
      );
    }

    // Orient coordinates from sub1 toward sub2 when sub1 is known (e.g. TORRINGTON TERMINAL -> FALLS VILLAGE)
    const sub1Match = POWER_SUBSTATIONS.find((s) => s.name === line.sub1);
    let orderedCoords = line.coordinates;
    if (sub1Match && line.coordinates.length >= 2) {
      const dStart = haversineMiles(
        sub1Match.lat,
        sub1Match.lng,
        line.coordinates[0][0],
        line.coordinates[0][1]
      );
      const dEnd = haversineMiles(
        sub1Match.lat,
        sub1Match.lng,
        line.coordinates[line.coordinates.length - 1][0],
        line.coordinates[line.coordinates.length - 1][1]
      );
      if (dEnd < dStart) {
        orderedCoords = [...line.coordinates].reverse();
      }
    }

    const townsTraversed: string[] = [];
    for (const [ptLat, ptLng] of orderedCoords) {
      let bestTown: string | null = null;
      let bestDist = Infinity;
      for (const wp of allWaypoints) {
        const d = haversineMiles(ptLat, ptLng, wp.lat, wp.lng);
        if (d < bestDist) {
          bestDist = d;
          bestTown = wp.name;
        }
      }
      if (bestTown && bestDist <= 2.8 && !townsTraversed.includes(bestTown)) {
        townsTraversed.push(bestTown);
      }
    }

    // Find power stations within 3.5 miles of any vertex on this line
    const nearbyStations: EnrichedTransmissionCorridor["nearbyStations"] = [];
    for (const st of POWER_STATIONS) {
      let minDist = Infinity;
      for (const [ptLat, ptLng] of line.coordinates) {
        const d = haversineMiles(st.lat, st.lng, ptLat, ptLng);
        if (d < minDist) minDist = d;
      }
      if (minDist <= 3.5) {
        nearbyStations.push({
          id: st.id,
          name: st.name,
          city: st.city,
          totalMW: st.totalMW,
          primaryFuel: st.primaryFuel,
          distanceMiles: Number(minDist.toFixed(1)),
        });
      }
    }
    nearbyStations.sort((a, b) => a.distanceMiles - b.distanceMiles);

    return {
      ...line,
      corridorName: `${line.sub1} ↔ ${line.sub2}`,
      lengthMiles: Number(lengthMiles.toFixed(1)),
      townsTraversed,
      nearbyStations: nearbyStations.slice(0, 6),
    };
  });
}

export function computeDataCenterGridConnects(
  facilities: FacilityLocation[],
  extraLines: TransmissionLineSegment[] = [],
  extraPlants: PowerStation[] = []
): DataCenterGridConnect[] {
  const allLines = [...TRANSMISSION_LINES, ...extraLines];
  const allPlants = [...POWER_STATIONS, ...extraPlants];
  const namedSubs = POWER_SUBSTATIONS.filter((s) => isNamedSubstation(s.name));
  const subPool = namedSubs.length > 0 ? namedSubs : POWER_SUBSTATIONS;

  return facilities
    .filter((f) => f.isDataCenter)
    .map((dc) => {
      const isCT = dc.stateOrCountry.includes("CT") || dc.stateOrCountry.includes("MA") || dc.stateOrCountry.includes("NY");

      // 1. Find nearest named substation
      let bestSub = subPool[0];
      let bestSubDist = Infinity;
      for (const sub of subPool) {
        const d = haversineMiles(dc.lat, dc.lng, sub.lat, sub.lng);
        if (d < bestSubDist) {
          bestSubDist = d;
          bestSub = sub;
        }
      }

      // 2. Find nearest transmission line vertex
      let bestLine = allLines[0];
      let bestTapLat = bestSub.lat;
      let bestTapLng = bestSub.lng;
      let bestLineDist = Infinity;

      for (const line of allLines) {
        for (const [ptLat, ptLng] of line.coordinates) {
          const d = haversineMiles(dc.lat, dc.lng, ptLat, ptLng);
          if (d < bestLineDist) {
            bestLineDist = d;
            bestLine = line;
            bestTapLat = ptLat;
            bestTapLng = ptLng;
          }
        }
      }

      // 3. Find nearest major generating plant (>= 5 MW)
      let bestPlant = allPlants[0];
      let bestPlantDist = Infinity;
      let bestZeroPlant = allPlants.find((p) => isZeroCarbonFuel(p.primaryFuel)) || allPlants[0];
      let bestZeroPlantDist = Infinity;

      for (const plant of allPlants) {
        if (plant.totalMW < 5) continue;
        const d = haversineMiles(dc.lat, dc.lng, plant.lat, plant.lng);
        if (d < bestPlantDist) {
          bestPlantDist = d;
          bestPlant = plant;
        }
        if (isZeroCarbonFuel(plant.primaryFuel) && d < bestZeroPlantDist) {
          bestZeroPlantDist = d;
          bestZeroPlant = plant;
        }
      }

      return {
        facilityId: dc.id,
        facilityName: dc.name,
        operator: dc.operator,
        subtype: dc.subtype as DataCenterSubtype,
        city: dc.city,
        stateOrCountry: dc.stateOrCountry,
        isConnecticut: isCT,
        facilityLat: dc.lat,
        facilityLng: dc.lng,
        powerCapacityMW: dc.powerCapacityMW || "N/A",
        utilityTerritory: inferUtilityTerritory(dc),
        interconnectTier: inferInterconnectTier(dc.subtype as DataCenterSubtype),
        nearestSubstationName: bestSub.name,
        nearestSubstationVoltageKV: bestSub.maxVoltageKV,
        nearestSubstationLat: bestSub.lat,
        nearestSubstationLng: bestSub.lng,
        distanceToSubstationMiles: Number(bestSubDist.toFixed(2)),
        nearestLineVoltageKV: bestLine.voltageKV,
        nearestLineOwner: bestLine.owner,
        nearestLineCorridor: `${bestLine.sub1} ↔ ${bestLine.sub2} (${bestLine.voltageKV} kV)`,
        nearestLineTapLat: bestTapLat,
        nearestLineTapLng: bestTapLng,
        distanceToLineMiles: Number(bestLineDist.toFixed(2)),
        nearestPlantName: bestPlant.name,
        nearestPlantMW: bestPlant.totalMW,
        nearestPlantFuel: bestPlant.primaryFuel,
        nearestPlantLat: bestPlant.lat,
        nearestPlantLng: bestPlant.lng,
        distanceToPlantMiles: Number(bestPlantDist.toFixed(1)),
        nearestZeroCarbonPlantName: bestZeroPlant.name,
        nearestZeroCarbonPlantMW: bestZeroPlant.totalMW,
        nearestZeroCarbonPlantFuel: bestZeroPlant.primaryFuel,
        nearestZeroCarbonPlantLat: bestZeroPlant.lat,
        nearestZeroCarbonPlantLng: bestZeroPlant.lng,
        distanceToZeroCarbonPlantMiles: Number(bestZeroPlantDist.toFixed(1)),
      };
    });
}
